    "flex min-h-0 w-full flex-col overflow-hidden",
    "data-[swipe-direction=down]:max-h-[96svh]",
    "data-[swipe-direction=up]:max-h-[96svh]",
    "data-snap-layout:data-[swipe-direction=down]:h-(--drawer-height,96svh)",
    "data-snap-layout:data-[swipe-direction=up]:h-(--drawer-height,96svh)",
    "data-snap-layout:data-[swipe-direction=down]:*:data-[slot=drawer-main]:max-h-[calc(100%-abs(var(--drawer-snap-point-offset-y,0px)))]",
    "data-snap-layout:data-[swipe-direction=up]:*:data-[slot=drawer-main]:max-h-[calc(100%-abs(var(--drawer-snap-point-offset-y,0px)))]",
    "data-snap-layout:data-[swipe-direction=left]:*:data-[slot=drawer-main]:max-w-[calc(100%-abs(var(--drawer-snap-point-offset-x,0px)))]",
    "data-snap-layout:data-[swipe-direction=right]:*:data-[slot=drawer-main]:max-w-[calc(100%-abs(var(--drawer-snap-point-offset-x,0px)))]",
    "data-nested-drawer-open:h-[calc(var(--stack-height)+var(--bleed))]",
    "data-nested-drawer-open:data-[swipe-direction=down]:translate-y-[calc(-1*var(--stack-peek))]",
    "data-nested-drawer-open:data-[swipe-direction=up]:translate-y-[var(--stack-peek)]",
    "data-nested-drawer-open:overflow-hidden",
    "data-nested-drawer-open:pointer-events-none",
    "data-nested-drawer-open:**:data-[slot=drawer-main]:opacity-0",
    "data-nested-drawer-open:data-nested-drawer-swiping:**:data-[slot=drawer-main]:opacity-100",
    "bg-popover",
    "text-popover-foreground",
    "shadow-lg/5",
    "outline-none",
    "not-data-nested-drawer-open:transition-[transform,scale,opacity] duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]",
    "duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] data-nested-drawer-open:transition-[height,scale,translate]",
    "data-swiping:select-none data-swiping:transition-none data-swiping:duration-0",
    "data-dragging:transition-none",
    "data-nested-drawer-swiping:duration-0",
    "data-[swipe-direction=down]:origin-[center_bottom]",
    "data-[swipe-direction=up]:origin-[center_top]",
    "motion-reduce:animate-none! motion-reduce:transition-none!",
    "after:pointer-events-none after:absolute after:bg-inherit after:content-['']",
    "data-[swipe-direction=down]:rounded-t-2xl",
    "data-[swipe-direction=down]:pb-[calc(1.5rem+env(safe-area-inset-bottom,0))]",
    "data-[swipe-direction=down]:after:inset-x-0 data-[swipe-direction=down]:after:top-full data-[swipe-direction=down]:after:h-(--bleed)",
    "data-[swipe-direction=down]:data-[state=open]:animate-drawer-slide-in-bottom",
    "data-[swipe-direction=down]:data-[state=closed]:animate-drawer-slide-out-bottom",
    "data-[swipe-direction=up]:rounded-b-2xl",
    "data-[swipe-direction=up]:pt-[env(safe-area-inset-top,0)]",
    "data-[swipe-direction=up]:after:inset-x-0 data-[swipe-direction=up]:after:bottom-full data-[swipe-direction=up]:after:h-(--bleed)",
    "data-[swipe-direction=up]:data-[state=open]:animate-drawer-slide-in-top",
    "data-[swipe-direction=up]:data-[state=closed]:animate-drawer-slide-out-top",
    "data-[swipe-direction=left]:h-full data-[swipe-direction=left]:max-h-none data-[swipe-direction=left]:min-h-0 data-[swipe-direction=left]:w-full data-[swipe-direction=left]:max-w-md",
    "data-snap-layout:data-[swipe-direction=left]:h-full data-snap-layout:data-[swipe-direction=left]:w-full data-snap-layout:data-[swipe-direction=left]:max-w-md",
    "data-[swipe-direction=left]:rounded-e-2xl",
    "data-[swipe-direction=left]:ps-[env(safe-area-inset-left,0)]",
    "data-[swipe-direction=left]:after:top-0 data-[swipe-direction=left]:after:right-full data-[swipe-direction=left]:after:bottom-0 data-[swipe-direction=left]:after:h-auto data-[swipe-direction=left]:after:w-(--bleed)",
    "data-[swipe-direction=left]:data-[state=open]:animate-drawer-slide-in-left",
    "data-[swipe-direction=left]:data-[state=closed]:animate-drawer-slide-out-left",
    "data-[swipe-direction=right]:h-full data-[swipe-direction=right]:max-h-none data-[swipe-direction=right]:min-h-0 data-[swipe-direction=right]:w-full data-[swipe-direction=right]:max-w-md",
    "data-snap-layout:data-[swipe-direction=right]:h-full data-snap-layout:data-[swipe-direction=right]:w-full data-snap-layout:data-[swipe-direction=right]:max-w-md",
    "data-[swipe-direction=right]:rounded-s-2xl",
    "data-[swipe-direction=right]:pe-[env(safe-area-inset-right,0)]",
    "data-[swipe-direction=right]:after:top-0 data-[swipe-direction=right]:after:bottom-0 data-[swipe-direction=right]:after:left-full data-[swipe-direction=right]:after:h-auto data-[swipe-direction=right]:after:w-(--bleed)",
    "data-[swipe-direction=right]:data-[state=open]:animate-drawer-slide-in-right",
    "data-[swipe-direction=right]:data-[state=closed]:animate-drawer-slide-out-right",
  ],
  variants: {
    variant: {
      default: "",
      inset: [
        "sm:rounded-2xl sm:border",
        "sm:**:data-[slot=drawer-footer]:rounded-b-[calc(var(--radius-2xl)-1px)]",
      ],
      straight: "rounded-none!",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

function hasSnapLayout(
  snapPoints: readonly (number | string)[],
  snapPoint: number | string | null
) {
  if (snapPoints.length > 1) {
    return true;
  }

  if (snapPoint == null) {
    return false;
  }

  return snapPoint !== 1 && snapPoint !== "1";
}

interface DrawerContentProps
  extends React.ComponentProps<typeof ArkDrawer.Content>,
    VariantProps<typeof drawerContentVariants> {
  /**
   * Show the drag bar indicator
   *
   * @default true
   */
  showBar?: boolean;
  /**
   * Show close button at the top right corner
   *
   * @default false
   */
  showCloseButton?: boolean;
}

const DrawerContentPanel = (props: DrawerContentProps) => {
  const {
    variant = "default",
    showBar,
    showCloseButton = false,
    className,
    children,
    draggable: draggableProp,
    onPointerDown,
    ...rest
  } = props;

  return (
    <ArkDrawer.Context>
      {({ snapPoints, snapPoint }) => {
        const shouldShowBar = showBar ?? true;
        const snapLayout = hasSnapLayout(snapPoints, snapPoint);

        return (
          <DrawerPositioner variant={variant === "inset" ? "inset" : "default"}>
            <ArkDrawer.Content
              className={cn(drawerContentVariants({ variant }), className)}
              data-slot="drawer-content"
              data-snap-layout={snapLayout || undefined}
              draggable={draggableProp ?? true}
              onPointerDown={(event) => {
                onPointerDown?.(event);
                event.stopPropagation();
              }}
              {...rest}
            >
              <DrawerGrabber show={shouldShowBar} />

              <ark.div
                className="flex min-h-0 flex-1 flex-col overflow-hidden transition-opacity duration-300 ease-in-out group-data-[swipe-direction=right]/drawer:ps-8 group-data-[swipe-direction=left]/drawer:pe-8 motion-reduce:transition-none!"
                data-slot="drawer-main"
              >
                {children}
              </ark.div>

              {!!showCloseButton && (
                <DrawerClose asChild>
                  <Button
                    aria-label="Close"
                    className="absolute inset-e-4 top-4 opacity-64 hover:opacity-100 group-data-[swipe-direction=up]/drawer:top-[calc(1rem+env(safe-area-inset-top,0))]"
                    size="icon-sm"
                    variant="ghost"
                  >
                    <XIcon aria-hidden />
                  </Button>
                </DrawerClose>
              )}
            </ArkDrawer.Content>
          </DrawerPositioner>
        );
      }}
    </ArkDrawer.Context>
  );
};

export const DrawerContent = (props: DrawerContentProps) => (
  <Portal>
    <DrawerOverlay />
    <DrawerContentPanel {...props} />
  </Portal>
);

interface DrawerGrabberProps
  extends React.ComponentProps<typeof ArkDrawer.Grabber> {
  /**
   * Whether to render the grabber
   *
   * @default true
   */
  show?: boolean;
}

export const DrawerGrabber = (props: DrawerGrabberProps) => {
  const { show = true, className, ...rest } = props;

  if (!show) {
    return null;
  }

  return (
    <ArkDrawer.Grabber
      className={cn(
        "hidden shrink-0 cursor-grab touch-none select-none active:cursor-grabbing",
        "group-data-[swipe-direction=down]/drawer:flex group-data-[swipe-direction=down]/drawer:w-full group-data-[swipe-direction=down]/drawer:items-center group-data-[swipe-direction=down]/drawer:justify-center group-data-[swipe-direction=down]/drawer:py-5",
        "group-data-[swipe-direction=up]/drawer:z-10 group-data-[swipe-direction=up]/drawer:order-last group-data-[swipe-direction=up]/drawer:flex group-data-[swipe-direction=up]/drawer:w-full group-data-[swipe-direction=up]/drawer:items-center group-data-[swipe-direction=up]/drawer:justify-center group-data-[swipe-direction=up]/drawer:py-5",
        "group-data-[swipe-direction=left]/drawer:absolute group-data-[swipe-direction=left]/drawer:inset-y-0 group-data-[swipe-direction=left]/drawer:end-0 group-data-[swipe-direction=left]/drawer:z-10 group-data-[swipe-direction=left]/drawer:flex group-data-[swipe-direction=left]/drawer:w-8 group-data-[swipe-direction=left]/drawer:items-center group-data-[swipe-direction=left]/drawer:justify-center",
        "group-data-[swipe-direction=right]/drawer:absolute group-data-[swipe-direction=right]/drawer:inset-y-0 group-data-[swipe-direction=right]/drawer:start-0 group-data-[swipe-direction=right]/drawer:z-10 group-data-[swipe-direction=right]/drawer:flex group-data-[swipe-direction=right]/drawer:w-8 group-data-[swipe-direction=right]/drawer:items-center group-data-[swipe-direction=right]/drawer:justify-center",
        "group-data-nested-drawer-open/drawer:hidden",
        "group-data-nested-drawer-swiping/drawer:flex",
        className
      )}
      data-slot="drawer-grabber"
      {...rest}
    >
      <ArkDrawer.GrabberIndicator
        className={cn(
          "h-1 w-10 rounded-full bg-muted-foreground/32 group-hover/drawer:bg-muted-foreground/48",
          "group-data-[swipe-direction=left]/drawer:rotate-90",
          "group-data-[swipe-direction=right]/drawer:rotate-90"
        )}
        data-slot="drawer-grabber-indicator"
      />
    </ArkDrawer.Grabber>
  );
};

interface DrawerHeaderProps extends React.ComponentProps<typeof ark.div> {
  /**
   * The description of the drawer
   */
  description?: string;
  /**
   * The title of the drawer
   */
  title?: string;
}

const drawerHeaderVariants = tv({
  base: [
    "shrink-0 touch-none",
    "flex flex-col gap-2",
    "p-(--space)",
    "in-[[data-slot=drawer-content]:has([data-slot=drawer-body])]:pb-3",
    "group-data-[swipe-direction=down]/drawer:pt-0",
  ],
});

export const DrawerHeader = (props: DrawerHeaderProps) => {
  const { className, title, description, children, ...rest } = props;

  return (
    <ark.div
      className={cn(drawerHeaderVariants(), className)}
      data-slot="drawer-header"
      {...rest}
    >
      {!!title && <DrawerTitle>{title}</DrawerTitle>}

      {!!description && <DrawerDescription>{description}</DrawerDescription>}

      {!title && typeof children === "string" ? (
        <DrawerTitle>{children}</DrawerTitle>
      ) : (
        children
      )}
    </ark.div>
  );
};

export const DrawerTitle = (
  props: React.ComponentProps<typeof ArkDrawer.Title>
) => {
  const { className, ...rest } = props;
  return (
    <ArkDrawer.Title
      className={cn("font-semibold text-lg leading-none", className)}
      data-slot="drawer-title"
      {...rest}
    />
  );
};

export const DrawerDescription = (
  props: React.ComponentProps<typeof ArkDrawer.Description>
) => {
  const { className, ...rest } = props;
  return (
    <ArkDrawer.Description
      className={cn("text-muted-foreground text-sm", className)}
      data-slot="drawer-description"
      {...rest}
    />
  );
};

interface DrawerBodyProps extends React.ComponentProps<typeof ark.div> {
  /**
   * Add a fade effect to the scroll area
   *
   * @default false
   */
  scrollFade?: boolean;
}

export const DrawerBody = (props: DrawerBodyProps) => {
  const { scrollFade = false, className, ...rest } = props;

  return (
    <ScrollArea
      className="min-h-0 flex-1 touch-pan-y"
      data-no-drag=""
      scrollFade={scrollFade}
    >
      <ark.div
        className={cn(
          "p-(--space)",
          "in-[[data-slot=drawer-content]:has([data-slot=drawer-header])]:pt-0",
          "group-data-[swipe-direction=down]/drawer:in-[[data-slot=drawer-content]:not(:has([data-slot=drawer-header]))]:pt-0",
          "in-[[data-slot=drawer-content]:has([data-slot=drawer-footer]:not(.border-t))]:pb-1",
          className
        )}
        data-slot="drawer-body"
        {...rest}
      />
    </ScrollArea>
  );
};

export const DrawerClose = (
  props: React.ComponentProps<typeof ArkDrawer.CloseTrigger>
) => <ArkDrawer.CloseTrigger data-slot="drawer-close" {...props} />;

const drawerFooterVariants = tv({
  base: [
    "shrink-0",
    "flex flex-col-reverse gap-2",
    "sm:rounded-none",
    "px-(--space) py-4",
  ],
  variants: {
    variant: {
      default: "border-t bg-muted/48",
      bare: "",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

interface DrawerFooterProps
  extends React.ComponentProps<typeof ark.div>,
    VariantProps<typeof drawerFooterVariants> {}

export const DrawerFooter = (props: DrawerFooterProps) => {
  const { variant = "default", className, ...rest } = props;

  return (
    <ark.div
      className={cn(drawerFooterVariants({ variant }), className)}
      data-slot="drawer-footer"
      {...rest}
    />
  );
};
